from collections import defaultdict


n, m = map(int, input().split())
E = [tuple(map(int, input().split())) for _ in range(m)]
adj = defaultdict(set)
for e in E:
    adj[e[0]].add(e[1])
    adj[e[1]].add(e[0])
dl = defaultdict(list)
for v in adj:
    dl[len(adj[v])].append(v)
if len(dl[1]) == 0:
    print('0')
else:
    cnt = 0
    cnt2 = sum(len(dl[x]) for x in dl.keys())
    while cnt2 > len(dl[1]):
        dec = defaultdict(int)
        while len(dl[1]) > 0:
            v = dl[1].pop()
            cnt2 -= 1
            for v2 in adj[v]:
                dec[v2] += 1              
                adj[v2].remove(v)
            del adj[v]
        cnt += 1
        for v in dec.keys():
            dl[len(adj[v]) + dec[v]].remove(v)
            if len(adj[v]) > 0:
                dl[len(adj[v])].append(v)
            else:
                cnt2 -= 1
    if len(dl[1]) > 0:
        cnt += 1
    print(cnt)

